import { useRef } from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(useGSAP, ScrollTrigger);

export function ScrollReveal() {
  const container = useRef<HTMLDivElement>(null);

  useGSAP(
    () => {
      gsap.utils.toArray<HTMLElement>(".reveal").forEach((el) => {
        gsap.from(el, {
          y: {{y}},
          opacity: 0,
          duration: {{duration}},
          ease: "{{ease}}",
          scrollTrigger: { trigger: el, start: "top {{start}}%", toggleActions: "play none none reverse" },
        });
      });
    },
    { scope: container },
  );

  return (
    <div ref={container}>
      <section className="reveal">One</section>
      <section className="reveal">Two</section>
      <section className="reveal">Three</section>
    </div>
  );
}
